-- REFERENCE ONLY.
create table if not exists relationship_agreement_reviews (id uuid primary key default gen_random_uuid(), agreement_id uuid not null, authority_verified boolean not null default false, exact_scope jsonb not null, effective_period tstzrange, state text not null, created_at timestamptz not null default now());
create table if not exists public_service_obligations (id uuid primary key default gen_random_uuid(), service_key text not null, mandate_source jsonb not null, minimum_service jsonb not null, appropriation_id uuid, state text not null, created_at timestamptz not null default now());
create table if not exists capacity_fund_replenishments (id uuid primary key default gen_random_uuid(), period daterange not null, target_amount numeric, currency text, state text not null, donor_concentration jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists host_privilege_reviews (id uuid primary key default gen_random_uuid(), jurisdiction text not null, legal_instrument jsonb not null, privilege_scope jsonb not null, remedy_path jsonb not null, state text not null, created_at timestamptz not null default now());
